<style>.pagination-custom{display:flex;justify-content:center;margin-top:1rem}.pagination-inner{display:flex;gap:4px;align-items:center;flex-wrap:wrap;padding:4px;border:1px solid #e8ebf3;border-radius:999px;background:#fff;box-shadow:0 6px 18px #18223814}.pagination-custom .page-link{display:inline-flex;align-items:center;justify-content:center;min-width:28px;height:28px;padding:0 9px;border:1px solid transparent;border-radius:999px;color:#182238;font-size:12px;text-decoration:none}.pagination-custom .page-link.active,.pagination-custom .page-link:hover{background:#ec2877;color:#fff}.pagination-custom .page-link.disabled{background:#f5f6f8;color:#a3a9b5}.thumb-placeholder{position:relative;display:grid;place-items:center;width:100%;height:100%;min-height:150px;overflow:hidden;background:linear-gradient(135deg,#252b43,#515b83);color:#fff}.lazy-thumbnail{width:100%;height:100%;min-height:150px;object-fit:cover;opacity:0;transition:opacity .2s ease}.thumb-placeholder.loaded{background:#252b43}.thumb-placeholder.loaded .lazy-thumbnail{opacity:1}.thumb-skeleton{position:absolute;width:65%;height:10px;border-radius:99px;background:linear-gradient(90deg,#ffffff20,#ffffff66,#ffffff20);background-size:200% 100%;animation:skeleton-shimmer 1.4s infinite}@keyframes skeleton-shimmer{to{background-position:-200% 0}}</style><div style="margin-top:24px"><?php echo e($videos->links('pagination.custom')); ?></div>
<script>
const search=document.querySelector('#liveSearch input');let searchTimer;search.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const url=new URL(search.form.action);new FormData(search.form).forEach((value,key)=>{if(value)url.searchParams.set(key,value);else url.searchParams.delete(key)});loadHomePage(url.toString())},350)});
document.querySelectorAll('.thumb-video').forEach(video=>{const thumb=video.closest('.thumb');const fallback=thumb.querySelector('.thumb-fallback');const duration=thumb.querySelector('.duration');video.addEventListener('loadedmetadata',()=>{if(video.duration>0){const seconds=Math.round(video.duration);duration.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;video.currentTime=Math.random()*video.duration*.85}},{once:true});video.addEventListener('error',()=>{video.hidden=true});thumb.addEventListener('pointerenter',()=>{if(video.readyState===0){video.preload='metadata';video.load()}});thumb.addEventListener('pointermove',event=>{if(!Number.isFinite(video.duration))return;video.hidden=false;if(fallback)fallback.hidden=true;const bounds=thumb.getBoundingClientRect();video.currentTime=Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width))*video.duration});thumb.addEventListener('pointerleave',()=>{if(fallback)fallback.hidden=false;video.pause()})});
window.initLazyThumbnails=()=>{const images=document.querySelectorAll('.lazy-thumbnail:not([src])');if(!('IntersectionObserver' in window)){images.forEach(image=>{if(image.dataset.src)image.src=image.dataset.src});return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const image=entry.target;if(!image.dataset.src){observer.unobserve(image);return}image.onload=()=>{image.closest('.thumb-placeholder')?.classList.add('loaded')};image.onerror=()=>{image.closest('.thumb-placeholder')?.classList.add('failed')};image.src=image.dataset.src;observer.unobserve(image)}),{rootMargin:'300px'});images.forEach(image=>observer.observe(image));const metadataObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const card=entry.target;const duration=card.querySelector('.duration');if(duration.textContent!=='--:--'){metadataObserver.unobserve(card);return}fetch(`/videos/${card.dataset.videoId}/metadata`,{headers:{Accept:'application/json'}}).then(response=>response.ok?response.json():null).then(data=>{if(data?.duration)duration.textContent=data.duration}).catch(()=>{});metadataObserver.unobserve(card)}),{rootMargin:'500px'});document.querySelectorAll('[data-video-id]').forEach(card=>metadataObserver.observe(card))};window.initLazyThumbnails();
</script>
<script>
const homeContent=document.querySelector('main');
async function loadHomePage(url, push=true){
    const response=await fetch(url,{headers:{'X-Requested-With':'XMLHttpRequest'}});
    if(!response.ok)return;
    const html=await response.text();
    const next=new DOMParser().parseFromString(html,'text/html');
    const currentCards=document.querySelector('.cards');
    const nextCards=next.querySelector('.cards');
    const currentPagination=document.querySelector('.pagination-custom')?.parentElement;
    const nextPagination=next.querySelector('.pagination-custom')?.parentElement;
    if(currentCards&&nextCards)currentCards.replaceWith(nextCards);
    if(currentPagination&&nextPagination)currentPagination.replaceWith(nextPagination);
    window.initLazyThumbnails?.();
    if(push)history.pushState({},'',url);
    window.scrollTo({top:0,behavior:'smooth'});
}
document.addEventListener('click',event=>{const link=event.target.closest('.pagination-custom a');if(!link||!link.href)return;event.preventDefault();loadHomePage(link.href)});
window.addEventListener('popstate',()=>loadHomePage(location.href,false));
document.getElementById('liveSearch')?.addEventListener('submit',event=>{event.preventDefault();const url=new URL(event.currentTarget.action);new FormData(event.currentTarget).forEach((value,key)=>{if(value)url.searchParams.set(key,value);else url.searchParams.delete(key)});loadHomePage(url.toString())});
document.getElementById('heroSearch')?.addEventListener('submit',event=>{event.preventDefault();const url=new URL(event.currentTarget.action);new FormData(event.currentTarget).forEach((value,key)=>{if(value)url.searchParams.set(key,value);else url.searchParams.delete(key)});loadHomePage(url.toString())});
</script>
<script>document.addEventListener('error',event=>{if(!event.target.matches?.('.lazy-thumbnail'))return;const box=event.target.closest('.thumb-placeholder');event.target.remove();box?.querySelector('.thumb-skeleton')?.remove();if(box&&!box.querySelector('.thumbnail-error')){const message=document.createElement('span');message.className='thumbnail-error';message.textContent='Preview unavailable';box.append(message)}},true);</script>
